# Kiểm chứng Bài 11.3: sự kiện đổi luật/cài đặt tường lửa trên Windows Server 2025 + lời giải 🧪 câu 2
@win New-NetFirewallRule -Name lab-8080 -DisplayName 'lab 8080' -Direction Inbound -Protocol TCP -LocalPort 8080 -Action Allow | Out-Null; Set-NetFirewallRule -Name lab-8080 -LocalPort 8081; Remove-NetFirewallRule -Name lab-8080; Set-NetFirewallProfile -Name Private -Enabled False; Set-NetFirewallProfile -Name Private -Enabled True; Start-Sleep 2
@win Get-WinEvent -LogName 'Microsoft-Windows-Windows Firewall With Advanced Security/Firewall' -MaxEvents 8 | Sort-Object TimeCreated | Select-Object TimeCreated,Id,@{n='Message';e={($_.Message -split "`r?`n")[0]}} | Format-Table -AutoSize -Wrap
@win $h = 'date','time','action','protocol','srcip','dstip','srcport','dstport','size','tcpflags','tcpsyn','tcpack','tcpwin','icmptype','icmpcode','info','path','pid'; $d = Get-Content "$env:SystemRoot\System32\LogFiles\Firewall\pfirewall.log" | Where-Object { $_ -and $_ -notmatch '^#' } | ConvertFrom-Csv -Delimiter ' ' -Header $h; $d | Where-Object action -eq 'DROP' | Group-Object dstport | Sort-Object Count -Descending | Select-Object -First 5 Count,Name
